func (v SpecValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	arguments := types.ListValueMust(
		ArgumentsType{
			basetypes.ObjectType{
				AttrTypes: ArgumentsValue{}.AttributeTypes(ctx),
			},
		},
		v.Arguments.Elements(),
	)

	if v.Arguments.IsNull() {
		arguments = types.ListNull(
			ArgumentsType{
				basetypes.ObjectType{
					AttrTypes: ArgumentsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Arguments.IsUnknown() {
		arguments = types.ListUnknown(
			ArgumentsType{
				basetypes.ObjectType{
					AttrTypes: ArgumentsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	var provider basetypes.ObjectValue

	if v.Provider.IsNull() {
		provider = types.ObjectNull(
			ProviderValue{}.AttributeTypes(ctx),
		)
	}

	if v.Provider.IsUnknown() {
		provider = types.ObjectUnknown(
			ProviderValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Provider.IsNull() && !v.Provider.IsUnknown() {
		provider = types.ObjectValueMust(
			ProviderValue{}.AttributeTypes(ctx),
			v.Provider.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"arguments": basetypes.ListType{
			ElemType: ArgumentsValue{}.Type(ctx),
		},
		"description": basetypes.StringType{},
		"enabled":     basetypes.BoolType{},
		"mime_type":   basetypes.StringType{},
		"provider": basetypes.ObjectType{
			AttrTypes: ProviderValue{}.AttributeTypes(ctx),
		},
		"title":        basetypes.StringType{},
		"uri_template": basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"arguments":    arguments,
			"description":  v.Description,
			"enabled":      v.Enabled,
			"mime_type":    v.MimeType,
			"provider":     provider,
			"title":        v.Title,
			"uri_template": v.UriTemplate,
		})

	return objVal, diags
}

func (v SpecValue) Equal(o attr.Value) bool {
	other, ok := o.(SpecValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Arguments.Equal(other.Arguments) {
		return false
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Enabled.Equal(other.Enabled) {
		return false
	}

	if !v.MimeType.Equal(other.MimeType) {
		return false
	}

	if !v.Provider.Equal(other.Provider) {
		return false
	}

	if !v.Title.Equal(other.Title) {
		return false
	}

	if !v.UriTemplate.Equal(other.UriTemplate) {
		return false
	}

	return true
}

